using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_current_weather")]
    [System.ComponentModel.Description("Gets the current weather for a given city name.")]
    public async Task<string> GetCurrentWeatherAsync(
        [System.ComponentModel.Description("The city name, e.g. 'London' or 'New York'")] string city,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"current.json?key=YOUR_API_KEY&q={Uri.EscapeDataString(city)}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        var current = json.GetProperty("current");

        return $"""
            Weather in {city}:
            Temperature: {current.GetProperty("temp_c")}°C
            Condition: {current.GetProperty("condition").GetProperty("text")}
            Humidity: {current.GetProperty("humidity")}%
            Wind: {current.GetProperty("wind_kph")} km/h
            """;
    }

    [McpServerTool(Name = "get_forecast")]
    [System.ComponentModel.Description("Gets a multi-day weather forecast for a city.")]
    public async Task<string> GetForecastAsync(
        [System.ComponentModel.Description("The city name")] string city,
        [System.ComponentModel.Description("Number of days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"forecast.json?key=YOUR_API_KEY&q={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        var forecastDays = json.GetProperty("forecast").GetProperty("forecastday");

        var lines = new List<string> { $"Forecast for {city}:" };
        foreach (var day in forecastDays.EnumerateArray())
        {
            var date = day.GetProperty("date").GetString();
            var dayData = day.GetProperty("day");
            lines.Add($"  {date}: {dayData.GetProperty("condition").GetProperty("text")} " +
                       $"High: {dayData.GetProperty("maxtemp_c")}°C " +
                       $"Low: {dayData.GetProperty("mintemp_c")}°C");
        }

        return string.Join("\n", lines);
    }
}
EOF

